import {PROFILE_INDEX,SAVE_KEYS,savedKey,createResilientStorage,snapshotWorkspace,validateBackup,restoreWorkspace} from './save-tools.js';
export function learnerStorage(storage,id){const key=k=>id==='original'?k:`fx:${id}:${k}`;return{get memoryOnly(){return !!storage.memoryOnly;},getItem:k=>storage.getItem(key(k)),setItem:(k,v)=>storage.setItem(key(k),v),removeItem:k=>storage.removeItem(key(k))};}
export function learningSignals(f,p){
 const out=[];
 if(!f||f.phase==='welcome')out.push({mission:'Fraction Foundry',status:'Not started',evidence:'No fraction activity recorded.',next:'Compare one half and one quarter from equal-sized wholes.'});
 else{const rejected=(f.events||[]).filter(e=>e.type==='patch_tested'&&(e.candidate!=='smaller'||e.reason==='same')).length;const wrong=(f.experiments||[]).filter(e=>e.choice!==e.truth).length,checks=(f.checks||[]).filter(c=>c.choice!==null),missed=checks.filter(c=>c.choice!==c.truth);out.push({mission:'Fraction Foundry',status:f.phase==='complete'?'Visit finished':`At ${f.phase}`,evidence:`${wrong} incorrect practice comparisons · ${rejected} rejected repairs · ${missed.length}/${checks.length} checks missed · ${(f.hints||[]).length} hints${f.adultHelp?' · tutor help recorded':''}`,next:missed.length?'Revisit the missed pairs with aligned shaded pieces, then try an unfamiliar pair.':!f.witness?'Line up two shaded pieces and find where Pip’s choice disagrees.':!f.repairPassed?'Use the saved pair to explain why more equal parts makes each piece smaller.':checks.length<3?'Finish the remaining comparisons before choosing the next practice.':'Try an unfamiliar pair next session and ask the learner to explain their choice.'});}
 if(!p)out.push({mission:'Pattern Grove',status:'Not started',evidence:'No pattern activity recorded.',next:'Say a two-tile loop aloud and choose the next tile.'});
 else{const wrong=(p.answers||[]).filter(a=>!a.correct).length;out.push({mission:'Pattern Grove',status:p.phase==='complete'?'Visit finished':`At ${p.phase}`,evidence:`${wrong}/${(p.answers||[]).length} checks missed · ${p.hints||0} hints · ${p.wrongTests??'not recorded'} incorrect practice choices · ${p.wrongRepairs??'not recorded'} rejected repairs`,next:wrong?'Trace one whole loop aloud. Rebuild a missed pattern before trying a new one.':!p.witness?'Use two different tiles to find a next tile that disagrees with Pip.':!p.repaired?'Compare “copy the last tile” with “repeat the whole loop.”':p.phase!=='complete'?'Finish the remaining patterns; help can stay available.':'Try a different three-tile loop next session. The built-in checks repeat on retries.'});}return out;
}
if(typeof window!=='undefined'){window.fixiverseSignals=learningSignals;let browserStore;try{browserStore=localStorage;}catch{}const native=createResilientStorage(browserStore,()=>window.dispatchEvent(new Event('fixiverse-storage-warning')));const INDEX=PROFILE_INDEX;let model;
try{model=JSON.parse(native.getItem(INDEX)||'null');}catch{}
if(!model||!Array.isArray(model.learners)||!model.learners.length){model={active:'original',learners:[{id:'original',alias:'First learner'}]};try{native.setItem(INDEX,JSON.stringify(model));}catch{}}
if(!model.learners.some(p=>p.id===model.active))model.active=model.learners[0].id;
// Cache every learner before any write can fail, so an emergency backup stays complete.
for(const p of model.learners)for(const k of SAVE_KEYS)native.getItem(savedKey(p.id,k));
native.setItem(INDEX,JSON.stringify(model));
window.fixiverseStorage=learnerStorage(native,model.active);
const requireSaving=()=>{if(native.memoryOnly)throw Error('This visit is in temporary memory. Download a workspace backup before changing learners.');};
const saveSelection=next=>{requireSaving();native.setItem(INDEX,JSON.stringify(next));if(native.memoryOnly){native.setItem(INDEX,JSON.stringify(model));requireSaving();}model=next;location.hash='tutor';location.reload();};
window.fixiverseProfiles={memoryOnly:()=>native.memoryOnly,list:()=>structuredClone(model.learners),active:()=>model.active,backup:()=>snapshotWorkspace(native,model),validateBackup,restoreBackup:data=>{const result=restoreWorkspace(native,model,data,()=>crypto.randomUUID());model=result.model;return result.added;},read:(id,k)=>{try{return JSON.parse(learnerStorage(native,id).getItem(k)||'null');}catch{return null;}},rename:alias=>{alias=String(alias).trim().slice(0,40);if(!alias)throw Error('Enter a nickname.');if(model.learners.some(p=>p.id!==model.active&&p.alias.toLowerCase()===alias.toLowerCase()))throw Error('That nickname is already in use.');const next={...model,learners:model.learners.map(p=>p.id===model.active?{...p,alias}:p)};native.setItem(INDEX,JSON.stringify(next));model=next;},select:id=>{if(!model.learners.some(p=>p.id===id))throw Error('Choose a learner.');if(model.active===id)return;saveSelection({...model,active:id});},add:alias=>{alias=String(alias).trim().slice(0,40);if(!alias)throw Error('Enter a learner nickname.');requireSaving();if(model.learners.some(p=>p.alias.toLowerCase()===alias.toLowerCase()))throw Error('That nickname is already in use. Choose another.');const id=crypto.randomUUID();saveSelection({...model,active:id,learners:[...model.learners,{id,alias}]});}};

}
